const LEVELS = [
 {id:'b1',name:'B1',kicker:'01 / XÂY LẠI NỀN TẢNG',headline:'Nắm chắc nền tảng.<br><em>Hiểu từng câu.</em>',desc:'Ôn lại những cấu trúc quen thuộc, từ hiện tại đơn đến hiện tại hoàn thành. Không chỉ nhớ công thức: hãy hiểu vì sao người nói chọn cấu trúc đó.',goal:'Kể thói quen, trải nghiệm và kế hoạch một cách rõ ràng.',art:'I <b>have lived</b> in Hanoi since 2020.',meaning:'Tôi sống ở Hà Nội từ năm 2020 đến nay.',memory:'Perfect ≠ đã xong',note:'Hiện tại hoàn thành có thể diễn tả một tình trạng vẫn tiếp tục. Điểm quan trọng là nhìn từ hiện tại về trước.',timeline:'present-perfect'},
 {id:'b1plus',name:'B1+',kicker:'02 / KẾT NỐI KIẾN THỨC',headline:'Từ biết công thức.<br><em>Đến chọn đúng.</em>',desc:'Kết nối các thì, mở rộng câu và xử lý những cặp dễ nhầm. Hiểu sự khác nhau giữa kết quả, quá trình, thói quen và kế hoạch.',goal:'Diễn đạt có liên kết, giải thích lý do và mô tả quá trình.',art:'I <b>have been debugging</b> for two hours.',meaning:'Tôi đã sửa lỗi được hai tiếng; đang nhấn mạnh quá trình.',memory:'Kết quả hay quá trình?',note:'Have fixed three bugs: ba lỗi đã sửa xong. Have been fixing bugs: tập trung vào hoạt động, không khẳng định số lỗi đã sửa xong.',timeline:'present-perfect-continuous'},
 {id:'b2',name:'B2',kicker:'03 / DIỄN ĐẠT LINH HOẠT',headline:'Thêm chiều sâu.<br><em>Rõ sắc thái.</em>',desc:'Kể sự kiện có thứ tự, nói về giả định và tổ chức ý phức tạp. Dùng ngữ pháp để diễn đạt điều bạn thực sự muốn nói.',goal:'Giải thích lập luận, thuật lại thông tin và bàn về tình huống giả định.',art:'By Friday, we <b>will have finished</b> testing.',meaning:'Đến thứ Sáu, chúng tôi sẽ hoàn tất kiểm thử.',memory:'Đứng ở một mốc tương lai',note:'Will be testing: đang kiểm thử tại mốc đó. Will have finished: công việc đã xong trước hoặc chậm nhất tại mốc đó.',timeline:'future-perfect'},
 {id:'b2plus',name:'B2+',kicker:'04 / TINH CHỈNH CÁCH DÙNG',headline:'Chính xác hơn.<br><em>Tự nhiên hơn.</em>',desc:'Kết hợp thời gian, rút gọn câu và thay đổi điểm nhấn. Một số bài cuối là phần mở rộng nâng cao; ưu tiên dùng chắc cấu trúc thông dụng trước.',goal:'Điều chỉnh điểm nhấn, mức độ chắc chắn và độ trang trọng.',art:'If I had slept earlier, I <b>would feel</b> better now.',meaning:'Nếu tối qua ngủ sớm hơn, bây giờ tôi đã thấy khỏe hơn.',memory:'Quá khứ → hiện tại',note:'Điều kiện hỗn hợp cho phép nguyên nhân ở quá khứ tạo ra một kết quả giả định ở hiện tại.',timeline:'mixed'}
];
const LESSONS=[];
function lesson(id,level,title,vi,idea,forms,uses,signals,examples,trap,memory,compare,q,options,answer,reasons,timeline='none'){
 LESSONS.push({id,level,title,vi,idea,forms,uses,signals,examples:examples.map(e=>({en:e[0],vi:e[1],why:e[2]})),trap,memory,compare,quiz:{q,options,answer,reasons},timeline});
}
const F={
 ps:['S + V / V-s/es','S + do/does not + V','Do/Does + S + V?'],
 pc:['S + am/is/are + V-ing','S + am/is/are not + V-ing','Am/Is/Are + S + V-ing?'],
 past:['S + V2 / V-ed','S + did not + V','Did + S + V?'],
 pastc:['S + was/were + V-ing','S + was/were not + V-ing','Was/Were + S + V-ing?'],
 pp:['S + have/has + V3','S + have/has not + V3','Have/Has + S + V3?'],
 future:['S + will + V','S + will not + V','Will + S + V?'],
 ppc:['S + have/has been + V-ing','S + have/has not been + V-ing','Have/Has + S + been + V-ing?'],
 pastp:['S + had + V3','S + had not + V3','Had + S + V3?'],
 pastpc:['S + had been + V-ing','S + had not been + V-ing','Had + S + been + V-ing?'],
 fc:['S + will be + V-ing','S + will not be + V-ing','Will + S + be + V-ing?'],
 fp:['S + will have + V3','S + will not have + V3','Will + S + have + V3?'],
 fpc:['S + will have been + V-ing','S + will not have been + V-ing','Will + S + have been + V-ing?']
};
lesson('present-simple','b1','Present Simple','Hiện tại đơn','Nhìn sự việc như một thói quen, sự thật hoặc trạng thái; không nhất thiết đang xảy ra ngay lúc nói.',F.ps,
 ['Thói quen, lịch sinh hoạt: I work on weekdays.','Sự thật và trạng thái: Water boils at 100°C at sea level.','Lịch trình cố định trong tương lai: The train leaves at six.','Với be, dùng am/is/are; không dùng do/does.'],
 'often, usually, every day — gợi ý thói quen, không phải quy tắc chọn thì tuyệt đối.',
 [['I check my emails every morning.','Tôi kiểm tra email mỗi sáng.','Thói quen lặp lại, không phải hành động ngay lúc này.'],['The market opens at nine tomorrow.','Thị trường mở cửa lúc chín giờ ngày mai.','Hiện tại đơn cũng dùng cho lịch trình đã ấn định.']],
 'She works → Does she work? / She does not work. Khi đã có does, động từ chính trở về nguyên mẫu. Thêm -es sau s, sh, ch, x, o; phụ âm + y → -ies (study → studies).',
 'Thói quen / sự thật / lịch trình','I work from home. → thói quen. I am working from home this week. → tình huống tạm thời.',
 'Every morning, my colleague ___ the server logs.',['check','checks','is check','checking'],1,
 ['Chủ ngữ my colleague là số ít; câu khẳng định cần -s.','Đúng: thói quen hằng sáng và chủ ngữ số ít.','Sau is cần V-ing nếu dùng tiếp diễn; is check không đúng cấu trúc.','V-ing đứng một mình không tạo vị ngữ chia thì.'],'present-simple');
lesson('present-continuous','b1','Present Continuous','Hiện tại tiếp diễn','Nhìn một hoạt động đang diễn ra ngay lúc này hoặc trong giai đoạn hiện tại; thường có tính tạm thời.',F.pc,
 ['Hành động đang diễn ra: I am reading now.','Tình huống tạm thời: We are using a test server this week.','Xu hướng thay đổi: More people are using mobile banking.','Sắp xếp tương lai đã chốt: I am meeting my manager tomorrow.'],
 'now, at the moment, this week — phải xem ngữ cảnh.',
 [['I am testing the Android app right now.','Tôi đang kiểm thử ứng dụng Android ngay bây giờ.','Hoạt động đang diễn ra.'],['We are staying with my parents this week.','Tuần này chúng tôi đang ở nhà bố mẹ tôi.','Tình huống tạm thời, không nhất thiết đúng tại từng giây.']],
 'Thường không dùng tiếp diễn với know, believe, own. I know the answer, không phải I am knowing. Động từ đổi nghĩa có thể dùng tiếp diễn: I am thinking about it. Bỏ -e trước -ing (make → making); lie → lying.',
 'Đang diễn ra / tạm thời','I live in Hanoi. → nơi ở hiện tại. I am living with a friend. → nhấn mạnh tạm thời. Có since 2020 và kéo dài đến nay: dùng dạng perfect.',
 'Please wait. I ___ the app right now.',['test','tested','am testing','have test'],2,
 ['Không diễn tả rõ hoạt động đang diễn ra mà câu này yêu cầu.','Quá khứ đơn không phù hợp right now trong ngữ cảnh này.','Đúng: am + V-ing cho hoạt động đang diễn ra.','Sau have trong perfect cần V3: tested.'],'present-continuous');
lesson('past-simple','b1','Past Simple','Quá khứ đơn','Đặt sự việc trong một bối cảnh quá khứ, thường là một sự kiện hoặc giai đoạn đã kết thúc.',F.past,
 ['Sự kiện đã xảy ra tại thời điểm quá khứ: yesterday, in 2022.','Chuỗi hành động: I arrived, opened my laptop and started working.','Trạng thái hoặc thói quen trong một giai đoạn quá khứ.','Với be: was/were; phủ định was not/were not; câu hỏi đảo was/were.'],
 'yesterday, last week, two days ago, in 2020.',
 [['I fixed the login bug yesterday.','Hôm qua tôi đã sửa lỗi đăng nhập.','Yesterday đặt sự việc vào quá khứ.'],['I lived in Hue for five years before moving to Hanoi.','Tôi đã sống ở Huế năm năm trước khi chuyển ra Hà Nội.','For vẫn dùng được với quá khứ đơn khi giai đoạn đã kết thúc.']],
 'Did you go?, không phải Did you went? Sau did/did not dùng V nguyên mẫu. Quá khứ đơn vẫn có thể có hậu quả hiện tại: I broke my leg yesterday. Không hiểu thành “quá khứ không liên quan hiện tại”.',
 'Kể chuyện ở mốc quá khứ','I lost my keys yesterday. → kể thời điểm xảy ra. I have lost my keys. → đưa việc mất vào bối cảnh hiện tại, thường là đang không có chìa khóa.',
 'We ___ the new version last Friday.',['release','have released','released','had release'],2,
 ['Hiện tại đơn không phù hợp mốc quá khứ last Friday.','Trong cách dùng chuẩn, present perfect không đi với mốc quá khứ đã kết thúc này.','Đúng: released là V2 cho sự kiện last Friday.','Past perfect cần had released; câu cũng không có mốc quá khứ thứ hai yêu cầu nhìn lùi.'],'past-simple');
lesson('past-continuous','b1','Past Continuous','Quá khứ tiếp diễn','Đặt mình vào một thời điểm quá khứ và nhìn hoạt động đang diễn ra tại thời điểm đó.',F.pastc,
 ['Hoạt động đang diễn ra ở một mốc quá khứ.','Tạo bối cảnh cho sự kiện xen vào: I was working when he called.','Hai hoạt động song song: while I was cooking, he was reading.'],
 'at 8 last night, while, when — không phải cứ thấy when là chọn tiếp diễn.',
 [['I was testing the app when my manager called.','Tôi đang kiểm thử ứng dụng thì quản lý gọi.','Was testing là nền; called là sự kiện xen vào.'],['At nine last night, the children were sleeping.','Lúc chín giờ tối qua, các con đang ngủ.','Nhìn vào quá trình tại mốc chín giờ.']],
 'I was working when the server crashed. Không cần cả hai động từ đều tiếp diễn. While thường mở bối cảnh kéo dài, nhưng cách chọn thì vẫn phụ thuộc ý nghĩa.',
 'Đang làm ở một mốc quá khứ','I tested the app. → kể việc kiểm thử. I was testing the app. → nhìn quá trình đang diễn ra.',
 'At 8 p.m. yesterday, I ___ dinner; I was halfway through cooking.',['cook','was cooking','have cooked','am cooking'],1,
 ['Hiện tại đơn không phù hợp mốc yesterday.','Đúng: quá trình đang diễn ra tại 8 p.m. hôm qua.','Present perfect không phù hợp mốc quá khứ cụ thể ở đây.','Am cooking là hiện tại tiếp diễn, không phải quá khứ.'],'past-continuous');
lesson('present-perfect','b1','Present Perfect','Hiện tại hoàn thành','Nhìn từ hiện tại về một sự việc hoặc trạng thái có trước hiện tại. Perfect không bắt buộc có nghĩa là “đã xong”.',F.pp,
 ['Trải nghiệm đến hiện tại, không nêu mốc quá khứ cụ thể.','Sự việc có kết quả đang được quan tâm ở hiện tại.','Trạng thái bắt đầu trước đây và vẫn tiếp tục: have known / have lived.','Kết quả trong khoảng thời gian tính đến hiện tại: so far, this week.'],
 'since + mốc; for + khoảng; ever, never, yet, already, so far. Since/for không tự động quyết định thì.',
 [['My brother has lived in Hanoi since 2020.','Anh tôi sống ở Hà Nội từ năm 2020 đến nay.','Has lived không có nghĩa là đã sống xong.'],['I have finished three reports so far today.','Tính đến lúc này hôm nay, tôi đã hoàn thành ba báo cáo.','Nhấn mạnh kết quả tính đến hiện tại.']],
 'I have seen him yesterday → I saw him yesterday. This morning: nếu đã sang buổi chiều/tối, thường dùng quá khứ đơn. Kể một sự kiện đã xong trong hôm nay cũng có thể dùng quá khứ đơn theo ngữ cảnh; đừng chọn thì chỉ bằng từ khóa.',
 'Trước đây → nhìn từ hiện tại','I lived here for five years. → một giai đoạn quá khứ. I have lived here for five years. → thường hiểu là đến nay vẫn sống ở đây.',
 'My brother still lives here. He ___ in Hanoi since 2020.',['lives','lived','has lived','is living'],2,
 ['Hiện tại đơn không diễn tả khoảng từ 2020 đến nay bằng cấu trúc since này.','Quá khứ đơn không phù hợp tình trạng vẫn tiếp tục được nêu rõ.','Đúng: has + V3 cho tình trạng từ quá khứ đến hiện tại.','Hiện tại tiếp diễn không nối được thời điểm bắt đầu 2020 với hiện tại trong cấu trúc này.'],'present-perfect');
lesson('future-simple','b1','Future with will','Tương lai đơn theo cách học phổ biến','Will thường dùng cho dự đoán, lời hứa, đề nghị hoặc quyết định ngay lúc nói.',F.future,
 ['Quyết định ngay lúc nói: I will help you.','Dự đoán / nhận định: I think the app will be popular.','Lời hứa, lời đề nghị: I will send you the file.','Will là động từ tình thái; “tương lai đơn” là tên quen thuộc trong cách học 12 dạng.'],
 'tomorrow, next week — mọi cách nói tương lai đều có thể dùng các cụm này.',
 [['The phone is ringing. I will answer it.','Điện thoại đang reo. Để tôi nghe máy.','Quyết định tại thời điểm nói.'],['I think the new feature will be useful.','Tôi nghĩ tính năng mới sẽ hữu ích.','Dự đoán dựa trên nhận định.']],
 'Sau will dùng V nguyên mẫu: will go, không phải will goes / will to go. Sau if/when trong mệnh đề điều kiện/thời gian tương lai thông thường: when he arrives, không phải when he will arrive.',
 'Will + động từ nguyên mẫu','Will: quyết định/lời hứa/dự đoán. Going to: ý định có trước hoặc dấu hiệu hiện tại. Present continuous: sắp xếp đã chốt.',
 '“I cannot carry this box.” — “I ___ you.” (an offer made now)',['helped','will help','am help','will helping'],1,
 ['Helped nói về quá khứ, không phải lời đề nghị lúc này.','Đúng: will help là lời đề nghị giúp ngay lúc nói.','Am help sai cấu trúc.','Sau will cần động từ nguyên mẫu: help.'],'future-simple');
lesson('basic-modals','b1','Can, must & should','Khả năng, nghĩa vụ và lời khuyên','Chọn modal theo ý định: có thể, bắt buộc, nên; cùng một động từ chính nhưng thái độ người nói khác nhau.',
 ['S + can/must/should + V','S + cannot/must not/should not + V','Can/Should + S + V?'],
 ['Can/could: khả năng hoặc yêu cầu lịch sự.','Must/have to: nghĩa vụ; have to có thể chia thì.','Must not: cấm. Do not have to: không cần, được quyền làm.','Should: lời khuyên, mức độ nhẹ hơn must.'],
 'Ý nghĩa quyết định lựa chọn, không có từ khóa nhận biết cố định.',
 [['You must not share your OTP.','Bạn không được chia sẻ OTP.','Must not diễn tả cấm.'],['You do not have to work this Sunday.','Chủ nhật này bạn không cần làm việc.','Không bắt buộc; không có nghĩa bị cấm làm.']],
 'Must not ≠ do not have to. She can swim, không phải She cans swim. Have to dùng does/did: Does she have to go?',
 'Cấm ≠ không bắt buộc','You should rest. → lời khuyên. You must wear a helmet. → nghĩa vụ.',
 'This meeting is optional. You ___ attend.',['must not','do not have to','cannot','must'],1,
 ['Must not là bị cấm, trái nghĩa optional.','Đúng: optional nghĩa là không bắt buộc tham dự.','Cannot nói không thể/không được, không phải optional.','Must là bắt buộc, trái với optional.']);
lesson('articles','b1','A, an & the','Mạo từ và không dùng mạo từ','A/an giới thiệu một đối tượng chưa xác định; the chỉ đối tượng người nghe nhận diện được. Một số nghĩa khái quát không dùng mạo từ.',
 ['a/an + danh từ đếm được số ít','the + danh từ đã xác định','Ø + danh từ số nhiều / không đếm được khi nói chung'],
 ['A/an với danh từ đếm được số ít, a developer, an engineer.','The khi đã nhắc, có ngữ cảnh xác định, hoặc là duy nhất trong tình huống.','Nói chung: Children need sleep. Water is important.','Chọn a/an theo âm, không theo chữ: a university, an hour.'],
 'Hỏi: danh từ đếm được không? Số ít không? Người nghe biết đối tượng nào chưa?',
 [['I found a bug. The bug affects login.','Tôi phát hiện một lỗi. Lỗi đó ảnh hưởng đăng nhập.','Lần đầu a, nhắc lại the.'],['He is an engineer at a securities company.','Anh ấy là kỹ sư ở một công ty chứng khoán.','Nghề nghiệp dùng a/an; engineer bắt đầu bằng âm nguyên âm.']],
 'I am developer → I am a developer. An university → a university vì âm đầu là /j/. Không dùng a với information: a piece of information.',
 'Một đối tượng → đối tượng đó','A report: một báo cáo chưa xác định. The report you sent: báo cáo cụ thể bạn đã gửi.',
 'She is ___ engineer.',['a','an','the','no article'],1,
 ['Engineer bắt đầu bằng âm nguyên âm nên không dùng a.','Đúng: an + danh từ nghề nghiệp số ít, chưa xác định.','The cần bối cảnh xác định cụ thể một kỹ sư nào đó.','Danh từ nghề nghiệp đếm được số ít cần mạo từ trong câu này.']);
lesson('countability','b1','Countable & uncountable','Danh từ đếm được và không đếm được','Đếm từng đơn vị hay nhìn như một lượng? Phân biệt này quyết định a/an, số nhiều, much và many.',
 ['many / a few + danh từ số nhiều','much / a little + danh từ không đếm được','a piece of / an item of + danh từ phù hợp'],
 ['Countable: a task, two tasks, many tasks.','Uncountable trong cách dùng thường gặp: advice, information, equipment.','A lot of dùng được cho cả hai nhóm.','Một số từ đổi cách đếm theo nghĩa: coffee (chất) / two coffees (hai cốc).'],
 'many/few cho số lượng; much/little cho lượng.',
 [['I need some advice about this error.','Tôi cần một ít lời khuyên về lỗi này.','Advice thường là không đếm được.'],['We have a few tasks left.','Chúng tôi còn vài việc nữa.','Tasks là đếm được số nhiều; a few có nghĩa có một số.']],
 'An advice / advices → some advice / a piece of advice. Few = ít đến mức gần như không đủ; a few = có một vài. Little và a little cũng khác sắc thái tương tự.',
 'Many tasks · much information','A few tasks: còn vài việc. Little time: gần như không có nhiều thời gian.',
 'There are ___ bugs left; only three.',['much','a little','a few','a piece of'],2,
 ['Much dùng với không đếm được; bugs là đếm được số nhiều.','A little dùng cho lượng không đếm được.','Đúng: a few + bugs, một vài lỗi.','A piece of không dùng trực tiếp với bugs để nói ba lỗi.']);
lesson('zero-first','b1','Zero & First Conditional','Điều kiện loại 0 và loại 1','Loại 0 mô tả quan hệ thường đúng; loại 1 nói về điều kiện và kết quả có thể xảy ra trong tương lai.',
 ['Loại 0: If + present simple, present simple','Loại 1: If + present simple, will/can/may + V','Có thể đảo thứ tự hai mệnh đề'],
 ['Loại 0: quy luật, cách hệ thống hoạt động.','Loại 1: tình huống tương lai được xem là thực tế/có khả năng.','Unless thường có nghĩa if not.','Kết quả có thể là mệnh lệnh: If you see an error, tell me.'],
 'If không tự động có nghĩa điều kiện loại 1; cần nhìn cả hai mệnh đề.',
 [['If the OTP expires, the system rejects it.','Nếu OTP hết hạn, hệ thống từ chối nó.','Quy tắc thông thường → loại 0.'],['If the tests pass, we will release the app tomorrow.','Nếu kiểm thử đạt, ngày mai chúng tôi sẽ phát hành ứng dụng.','Một khả năng cụ thể trong tương lai → loại 1.']],
 'Trong điều kiện tương lai thông thường, dùng If the tests pass, không phải If the tests will pass. Will trong mệnh đề if có cách dùng riêng như sự sẵn lòng, học sau.',
 'Quy luật hay khả năng tương lai?','If it rains, the ground gets wet. → quy luật. If it rains tomorrow, we will stay home. → kế hoạch cụ thể.',
 'If the tests ___ tomorrow, we will deploy the update.',['pass','will pass','passed','had passed'],0,
 ['Đúng: mệnh đề if loại 1 dùng hiện tại đơn cho điều kiện tương lai.','Thông thường không dùng will ở mệnh đề điều kiện này.','Passed tạo giả định loại 2, không khớp will deploy.','Had passed thường thuộc điều kiện quá khứ, không khớp câu này.']);

lesson('present-perfect-continuous','b1plus','Present Perfect Continuous','Hiện tại hoàn thành tiếp diễn','Nhìn hoạt động bắt đầu trước hiện tại qua quá trình hoặc thời lượng. Hoạt động có thể còn tiếp tục hoặc vừa dừng và để lại dấu vết.',F.ppc,
 ['Hoạt động kéo dài đến nay: I have been studying for two hours.','Hoạt động gần đây giải thích dấu vết hiện tại: You are wet; has it been raining?','Hành động lặp lại gần đây: I have been going to bed late.'],
 'for, since, all morning, lately — kết hợp ý nghĩa quá trình.',
 [['I have been debugging the app for two hours.','Tôi đã sửa lỗi ứng dụng được hai giờ.','Nhấn thời lượng; không khẳng định đã sửa xong.'],['Your hands are dirty. Have you been repairing the bike?','Tay bạn bẩn quá. Bạn vừa sửa xe đạp à?','Hoạt động có thể đã dừng; dấu vết còn ở hiện tại.']],
 'I have been knowing him → I have known him. “Have been writing three reports” có thể đúng nếu đang làm ba báo cáo chưa xong; số lượng không tự động cấm dạng tiếp diễn.',
 'Bao lâu / quá trình / dấu vết','I have written three reports. → ba báo cáo đã xong. I have been writing reports. → hoạt động. Nếu đang làm ba báo cáo chưa xong, have been writing three reports có ngữ cảnh hợp lệ.',
 'I am still working on the same bug. I ___ it for two hours.',['fix','am fixing','have been fixing','fixed'],2,
 ['Hiện tại đơn không thể hiện quá trình từ trước đến hiện tại trong câu này.','Am fixing không phù hợp for two hours tính đến nay.','Đúng: hoạt động kéo dài đến hiện tại, được xác nhận vẫn đang làm.','Fixed thường kể một hoạt động ở quá khứ, không khớp đang tiếp tục.'],'present-perfect-continuous');
lesson('past-perfect','b1plus','Past Perfect','Quá khứ hoàn thành','Đứng tại một mốc quá khứ và nhìn lùi về việc xảy ra trước mốc đó.',F.pastp,
 ['Làm rõ sự kiện nào xảy ra trước một sự kiện quá khứ khác.','Thuật lại kinh nghiệm tính đến một mốc quá khứ.','Không bắt buộc dùng past perfect cho mọi hành động xảy ra trước; trật tự có thể đã rõ nhờ before/after.'],
 'by the time, already, before — cần có điểm tham chiếu quá khứ.',
 [['When I arrived, the meeting had already started.','Khi tôi đến, cuộc họp đã bắt đầu trước đó.','Bắt đầu trước lúc tôi đến.'],['I had never used that tool before I joined the team.','Trước khi vào nhóm, tôi chưa từng dùng công cụ đó.','Nhìn kinh nghiệm tính đến thời điểm gia nhập.']],
 'Đừng dùng had + V3 chỉ vì chuyện “rất lâu rồi”. I visited Hue in 2010 vẫn dùng past simple nếu chỉ kể một mốc quá khứ.',
 'Trước một mốc quá khứ','When I arrived, he left. → anh ấy đi khi tôi đến. When I arrived, he had left. → anh ấy đã đi trước lúc tôi đến.',
 'By the time I arrived at 9, the meeting ___ at 8:30.',['has started','had started','starts','will start'],1,
 ['Has started nhìn từ hiện tại, không phù hợp hai mốc quá khứ.','Đúng: cuộc họp bắt đầu trước lúc tôi đến.','Starts là hiện tại đơn, không phù hợp câu kể quá khứ này.','Will start là tương lai, trái với việc đã xảy ra.'],'past-perfect');
lesson('future-forms','b1plus','Will, going to & arrangements','So sánh các cách nói tương lai','Tương lai không chỉ có will. Cách chọn cấu trúc cho biết quyết định đã có trước hay vừa nảy ra, dự đoán dựa vào gì, và lịch đã chốt chưa.',
 ['will + V: lời hứa / quyết định / dự đoán','am/is/are going to + V: ý định / dấu hiệu','am/is/are + V-ing: sắp xếp; present simple: lịch trình'],
 ['Will: quyết định lúc nói hoặc dự đoán theo nhận định.','Going to: ý định có trước hoặc dự đoán có bằng chứng hiện tại.','Present continuous: hẹn/sắp xếp cụ thể đã chốt.','Present simple: lịch trình, giờ tàu, giờ mở cửa.'],
 'Tomorrow không quyết định cấu trúc. Hãy hỏi: kế hoạch, sắp xếp hay dự đoán?',
 [['Look at those dark clouds. It is going to rain.','Nhìn mây đen kia. Trời sắp mưa.','Dấu hiệu hiện tại làm căn cứ dự đoán.'],['I am meeting the team at ten tomorrow.','Ngày mai tôi có hẹn với nhóm lúc mười giờ.','Sắp xếp đã chốt.']],
 'Các dạng có thể chồng lấn; nhiều câu có hơn một cách nói đúng. Bài tập cần ngữ cảnh đủ rõ, không chấm chỉ vì thấy tomorrow.',
 'Ý định · sắp xếp · dự đoán','I will call him. → lời hứa/quyết định. I am going to call him. → ý định có trước. I am meeting him. → cuộc hẹn đã sắp xếp.',
 'We ___ the manager at ten tomorrow. (Choose the present continuous form.)',['will meet','are going to meet','are meeting','meet'],2,
 ['Will meet có thể đúng nghĩa tương lai, nhưng không phải dạng hiện tại tiếp diễn được yêu cầu.','Going to diễn tả ý định; không phải dạng tiếp diễn được yêu cầu.','Đúng: are meeting là hiện tại tiếp diễn dùng cho sắp xếp tương lai.','Meet là hiện tại đơn; không phải hiện tại tiếp diễn.']);
lesson('passive','b1plus','Passive voice','Câu bị động cơ bản','Đưa người/vật chịu tác động lên làm chủ ngữ khi kết quả hoặc đối tượng quan trọng hơn người thực hiện.',
 ['S + be (chia thì) + V3','S + be not + V3','Be (chia thì) + S + V3?'],
 ['Hiện tại: is/are tested. Quá khứ: was/were tested.','Perfect: has/have been tested. Tương lai: will be tested.','Thêm by + người thực hiện nếu cần; có thể bỏ nếu không quan trọng.','Thường chỉ động từ có tân ngữ mới chuyển bị động.'],
 'Xác định thì ở động từ be; giữ động từ chính ở V3.',
 [['The app is tested before every release.','Ứng dụng được kiểm thử trước mỗi lần phát hành.','Trọng tâm là ứng dụng và quy trình.'],['The bug was fixed by our team yesterday.','Lỗi được nhóm chúng tôi sửa hôm qua.','Was xác định quá khứ; fixed là V3.']],
 'The bug fixed yesterday không phải một câu bị động đầy đủ; cần was fixed. The accident was happened sai vì happen không có tân ngữ theo cách dùng này.',
 'Be chia thì + V3','The team fixed the bug. → chủ động, nhấn người làm. The bug was fixed. → bị động, nhấn lỗi đã được xử lý.',
 'The update ___ by our team yesterday.',['released','was released','has release','was releasing'],1,
 ['Released đứng một mình sẽ tạo nghĩa chủ động thiếu tự nhiên vì update không tự phát hành trong ngữ cảnh này.','Đúng: was + V3, bị động ở quá khứ.','Has release sai V3 và thiếu cấu trúc bị động.','Was releasing là chủ động tiếp diễn, không diễn tả được phát hành bởi nhóm.']);
lesson('relative-clauses','b1plus','Relative clauses','Mệnh đề quan hệ','Gắn thông tin mô tả ngay sau danh từ: người nào, vật nào, địa điểm nào. Dùng dấu phẩy để phân biệt thông tin xác định và bổ sung.',
 ['người + who/that + mệnh đề','vật + which/that + mệnh đề','bổ sung: danh từ, who/which ..., (không dùng that)'],
 ['Defining: xác định đối tượng, không dùng dấu phẩy.','Non-defining: thêm thông tin, có dấu phẩy, không dùng that.','Có thể bỏ đại từ khi nó làm tân ngữ trong defining clause.','Whose: sở hữu; where: nơi chốn.'],
 'Who/which làm chủ ngữ không được bỏ: The engineer who fixed it ...',
 [['The developer who fixed the bug is on leave.','Lập trình viên đã sửa lỗi đang nghỉ phép.','Who fixed the bug xác định người nào.'],['My laptop, which I bought last year, is still fast.','Máy tính của tôi, mua năm ngoái, vẫn chạy nhanh.','Thông tin mua năm ngoái chỉ bổ sung.']],
 'The man who he called me sai vì lặp chủ ngữ he. Trong mệnh đề có dấu phẩy không dùng that và không bỏ đại từ quan hệ.',
 'Xác định hay bổ sung?','The report (that) you sent ... → có thể bỏ that vì làm tân ngữ. The report that arrived ... → không bỏ that vì làm chủ ngữ.',
 'My laptop, ___ I bought last year, is still fast.',['that','which','what','who'],1,
 ['Không dùng that trong mệnh đề quan hệ bổ sung có dấu phẩy.','Đúng: which chỉ vật, làm tân ngữ của bought.','What không nối theo cách này sau danh từ laptop.','Who chỉ người, không chỉ laptop.']);
lesson('gerund-infinitive','b1plus','Gerund & infinitive','V-ing và to + V','Sau mỗi động từ, cấu trúc đi kèm có thể khác. Học theo cụm và nghĩa, thay vì một quy tắc chung cho mọi động từ.',
 ['enjoy / avoid / finish + V-ing','want / decide / hope + to + V','giới từ + V-ing; modal + V nguyên mẫu'],
 ['Enjoy, avoid, suggest, finish thường theo sau bằng V-ing.','Want, plan, decide, hope thường theo sau bằng to-infinitive.','Sau giới từ dùng V-ing: interested in learning.','To có thể là giới từ: look forward to hearing from you.'],
 'Ghi nhớ cả cụm: decide to do, avoid doing, good at doing.',
 [['I enjoy learning how systems work.','Tôi thích tìm hiểu hệ thống hoạt động thế nào.','Enjoy + V-ing.'],['We decided to postpone the release.','Chúng tôi quyết định hoãn phát hành.','Decide + to + V.']],
 'I look forward to hear from you → hearing. To trong cụm look forward to là giới từ, không phải dấu hiệu của to-infinitive.',
 'Nhớ cụm, không đoán đuôi','I enjoy reading. / I want to read. Ý nghĩa gần nhau nhưng cấu trúc sau động từ khác nhau.',
 'We decided ___ the tests again.',['running','to run','run','to running'],1,
 ['Decide thường không theo trực tiếp bằng V-ing.','Đúng: decide + to-infinitive.','Sau decided cần to run trong cấu trúc này.','To running không phải to-infinitive sau decide.']);
lesson('present-deduction','b1plus','Must, might & cannot','Suy đoán ở hiện tại','Modal cho biết độ chắc chắn của suy luận: must là rất có cơ sở, might là có thể, cannot là gần như không thể theo bằng chứng.',
 ['must / might / may / could + V','cannot + V: suy luận phủ định','modal + be + V-ing: suy đoán hoạt động đang diễn ra'],
 ['Must: suy luận rất chắc dựa trên bằng chứng.','Might/may/could: một khả năng.','Cannot/can’t: điều đó không thể đúng theo suy luận.','Must not không phải cách phủ định suy luận thông thường của must.'],
 'Bằng chứng và mức độ chắc chắn quan trọng hơn từ khóa.',
 [['The lights are off. They might be asleep.','Đèn tắt rồi. Có thể họ đang ngủ.','Chỉ là một khả năng; có thể họ đi vắng.'],['That cannot be my phone; mine is black.','Đó không thể là điện thoại của tôi; máy tôi màu đen.','Bằng chứng loại trừ.']],
 'He must be tired là suy luận, không phải “anh ấy bị bắt buộc mệt”. Modal phải được hiểu theo ngữ cảnh.',
 'Must: chắc · might: có thể','He must be home. → tôi suy ra anh ấy ở nhà. He must go home. → có thể là nghĩa vụ phải về nhà.',
 'That ___ be Tom; Tom is in another city today.',['must','cannot','should','has to'],1,
 ['Must là suy luận khẳng định, trái với bằng chứng.','Đúng: cannot loại trừ khả năng dựa trên vị trí của Tom.','Should thường là kỳ vọng/lời khuyên, không thể hiện loại trừ ở đây.','Has to thường chỉ nghĩa vụ hoặc suy luận khẳng định.']);
lesson('comparisons','b1plus','Comparatives & superlatives','So sánh hơn, nhất và ngang bằng','Chọn cấu trúc theo độ dài và dạng tính từ, rồi dùng than hoặc as để nối đối tượng so sánh.',
 ['adj-er / more + adj + than','the adj-est / the most + adj','as + adj + as; not as + adj + as'],
 ['Short adjectives: faster, smaller; long: more reliable.','Bất quy tắc: good → better → best; bad → worse → worst.','Mức độ: much/far/a lot + comparative; a little/slightly + comparative.','The more ..., the more ... diễn tả hai mức độ biến đổi cùng nhau.'],
 'Than đi với so sánh hơn; as ... as đi với so sánh ngang bằng.',
 [['This query is much faster than the old one.','Truy vấn này nhanh hơn nhiều so với truy vấn cũ.','Much tăng mức độ của faster.'],['The new screen is not as clear as the old one.','Màn hình mới không rõ bằng màn hình cũ.','Not as ... as mô tả mức độ thấp hơn.']],
 'More faster → faster. Very better → much better. Không dùng đồng thời -er và more cho cùng tính từ.',
 'Better, không phải more good','Faster than: nhanh hơn. As fast as: nhanh bằng. The fastest: nhanh nhất trong nhóm.',
 'This version is ___ than the previous one.',['more fast','fastest','much faster','very faster'],2,
 ['Fast thường dùng faster, không dùng more fast.','Fastest là so sánh nhất, không đi theo mẫu than này.','Đúng: much + comparative faster.','Very không dùng trực tiếp để bổ nghĩa faster; dùng much.']);
lesson('second-conditional','b1plus','Second Conditional','Điều kiện loại 2','Dùng hình thức quá khứ để tạo khoảng cách với thực tế: giả định ở hiện tại hoặc tương lai, không phải kể chuyện quá khứ.',
 ['If + past simple, would/could + V','If I were ..., I would ...','would not / could not + V'],
 ['Tình huống giả định hoặc khó xảy ra ở hiện tại/tương lai.','Lời khuyên: If I were you, I would ...','Were dùng với mọi chủ ngữ trong giả định trang trọng; was cũng gặp trong văn nói.'],
 'Đuôi quá khứ ở if không tự động có nghĩa thời gian quá khứ.',
 [['If I had more time, I would practise English every day.','Nếu có nhiều thời gian hơn, tôi sẽ luyện tiếng Anh mỗi ngày.','Giả định về hiện tại.'],['If I were you, I would back up the database first.','Nếu là bạn, tôi sẽ sao lưu cơ sở dữ liệu trước.','Lời khuyên dưới dạng giả định.']],
 'If I would have more time → If I had more time trong mẫu thông thường. Không cho would vào mệnh đề if chỉ vì tiếng Việt có “sẽ”.',
 'Quá khứ về hình thức, giả định về nghĩa','If I have time, I will help. → khả năng thực tế. If I had time, I would help. → đặt mình vào giả định khác thực tế.',
 'If I ___ you, I would check the logs first. (formal hypothetical form)',['am','were','will be','have been'],1,
 ['Am thuộc cách diễn đạt thực tế, không khớp giả định If I ... you.','Đúng: If I were you là mẫu lời khuyên giả định.','Will be không dùng trong mẫu điều kiện loại 2 này.','Have been là present perfect, không dùng trong mẫu này.']);
lesson('prepositions','b1plus','Prepositions','Giới từ thời gian, nơi chốn và cụm từ','Một số giới từ có quy tắc khái quát; nhiều cụm phải học theo tổ hợp. Đừng dịch từng từ từ tiếng Việt.',
 ['at + giờ; on + ngày; in + tháng/năm','since + mốc; for + khoảng thời gian','depend on / interested in / good at + danh từ hoặc V-ing'],
 ['At nine; on Monday; in October.','Không thêm at/on/in trước next, last, this, every trong các cụm thời gian thường gặp.','At chỉ điểm/địa điểm; in thường là bên trong/phạm vi; on thường là trên bề mặt.','By Friday: trước/chậm nhất thứ Sáu. Until Friday: kéo dài đến thứ Sáu.'],
 'Học cụm: at work, on time, in time, responsible for.',
 [['I started this job in September.','Tôi bắt đầu công việc này vào tháng Chín.','In + tháng.'],['Please finish the report by Friday.','Hãy hoàn thành báo cáo chậm nhất vào thứ Sáu.','By chỉ hạn chót, không phải quá trình kéo dài.']],
 'In next week → next week. Depend of → depend on. By và until không hoán đổi khi nói hạn chót hoàn thành.',
 'By = hạn chót · until = kéo dài','I will finish by six. → xong chậm nhất lúc sáu. I will work until six. → làm liên tục đến sáu.',
 'The meeting starts ___ Monday morning.',['in','at','on','for'],2,
 ['In dùng với tháng/năm hoặc in the morning khi không kèm ngày cụ thể.','At thường dùng với giờ hoặc các cụm cố định.','Đúng: on Monday morning, một buổi cụ thể gắn với ngày.','For chỉ khoảng hoặc mục đích, không dùng để chỉ ngày bắt đầu ở đây.']);

lesson('past-perfect-continuous','b2','Past Perfect Continuous','Quá khứ hoàn thành tiếp diễn','Đứng ở một mốc quá khứ và nhìn hoạt động đã kéo dài trước mốc đó; nhấn quá trình, thời lượng hoặc nguyên nhân.',F.pastpc,
 ['Hoạt động kéo dài trước một sự kiện quá khứ.','Giải thích tình trạng ở quá khứ: I was tired because I had been working.','Hoạt động có thể dừng ngay trước mốc hoặc tiếp tục đến mốc.'],
 'for two hours before ..., since ... by then.',
 [['I had been debugging for two hours when I found the cause.','Tôi đã sửa lỗi được hai giờ thì tìm ra nguyên nhân.','Thời lượng tính đến mốc tìm ra nguyên nhân.'],['She was tired because she had been running.','Cô ấy mệt vì trước đó đã chạy.','Nhấn hoạt động giải thích tình trạng ở quá khứ.']],
 'Had worked và had been working đều có thể đúng trong một số ngữ cảnh. Dạng tiếp diễn nhấn quá trình; dạng đơn thường nhấn kết quả. Không dùng had been knowing.',
 'Quá trình trước một mốc quá khứ','Had fixed three bugs: ba lỗi xong trước mốc. Had been fixing bugs: quá trình sửa lỗi trước mốc.',
 'He was exhausted. He ___ all night before the meeting. (focus on duration)',['has been working','had been working','is working','will work'],1,
 ['Has been working nhìn từ hiện tại, trong khi câu đang kể quá khứ.','Đúng: had been + V-ing nhấn quá trình trước cuộc họp.','Is working thuộc hiện tại.','Will work thuộc tương lai, không giải thích tình trạng đã xảy ra.'],'past-perfect-continuous');
lesson('future-continuous','b2','Future Continuous','Tương lai tiếp diễn','Hình dung mình ở một thời điểm tương lai và nhìn hoạt động sẽ đang diễn ra tại thời điểm ấy.',F.fc,
 ['Hoạt động đang diễn ra ở một mốc tương lai.','Sự việc dự kiến diễn ra theo tiến trình bình thường.','Hỏi kế hoạch một cách trung tính: Will you be using the car tonight?'],
 'this time tomorrow, at nine tomorrow.',
 [['At ten tomorrow, I will be attending a meeting.','Lúc mười giờ ngày mai, tôi sẽ đang dự một cuộc họp.','Nhìn vào quá trình tại mốc mười giờ.'],['This time next week, we will be travelling to Da Nang.','Giờ này tuần sau, chúng tôi sẽ đang đi Đà Nẵng.','Hoạt động đang diễn ra tại thời điểm tưởng tượng.']],
 'Will be work → will be working. Không tự động chọn dạng này chỉ vì có tomorrow; phải có ý đang diễn ra tại mốc.',
 'Sẽ đang làm tại mốc đó','I will test it tomorrow. → nói việc sẽ làm. At ten, I will be testing it. → hoạt động đang diễn ra lúc mười giờ.',
 'At 10 tomorrow, I ___ in a meeting; it runs from 9 to 11. (continuous form)',['will have sat','will be sitting','had sat','sit'],1,
 ['Will have sat nhìn kết quả trước mốc, không nhấn đang tham dự tại mốc.','Đúng: will be + V-ing cho hoạt động đang diễn ra lúc mười giờ.','Had sat thuộc quá khứ hoàn thành.','Sit là hiện tại đơn, không phải dạng tiếp diễn được yêu cầu.'],'future-continuous');
lesson('future-perfect','b2','Future Perfect','Tương lai hoàn thành','Đứng ở một mốc tương lai và nhìn về việc sẽ đã xảy ra hoặc đã hoàn tất trước/chậm nhất tại mốc đó.',F.fp,
 ['Kết quả hoàn tất trước một hạn trong tương lai.','Một trạng thái kéo dài được bao lâu tính đến mốc tương lai: will have known.','Mệnh đề thời gian tương lai thường dùng hiện tại: by the time you arrive.'],
 'by Friday, by then, by the time ...',
 [['By Friday, we will have finished testing.','Đến thứ Sáu, chúng tôi sẽ hoàn tất kiểm thử.','Nhìn kết quả tính đến hạn thứ Sáu.'],['By next June, I will have worked here for one year.','Đến tháng Sáu năm sau, tôi sẽ làm ở đây được một năm.','Không có nghĩa bắt buộc nghỉ việc vào tháng Sáu.']],
 'Will have finish → will have finished. Future perfect cũng không luôn nghĩa “xong hẳn”: trạng thái có thể tiếp tục sau mốc.',
 'Đến mốc đó, đã ...','At five, I will be writing. → đang viết. By five, I will have finished. → đã hoàn thành trước/chậm nhất năm giờ.',
 'By Friday, we ___ all the tests. (completed before the deadline)',['will have completed','will be completing','had completed','complete yesterday'],0,
 ['Đúng: will have + V3, hoàn tất trước/chậm nhất mốc tương lai.','Will be completing nhấn quá trình, không khẳng định hoàn tất trước hạn.','Had completed nhìn từ một mốc quá khứ.','Cụm này không đúng cấu trúc và yesterday trái mốc tương lai.'],'future-perfect');
lesson('reported-speech','b2','Reported speech','Câu tường thuật','Thuật lại lời nói theo góc nhìn của người kể. Đổi đại từ, thời gian và thì khi điểm nhìn đã thay đổi.',
 ['said (that) + mệnh đề; told + người + mệnh đề','asked if/whether + S + V (câu hỏi yes/no)','asked + từ hỏi + S + V; told/asked + người + to + V'],
 ['Khi lùi thì: present → past; past → past perfect; will → would.','Có thể không lùi khi thông tin vẫn đúng hoặc còn liên quan, tùy ngữ cảnh.','Câu hỏi tường thuật dùng trật tự câu khẳng định.','Say không cần tân ngữ người; tell thường cần người được nói với.'],
 'now → then, today → that day chỉ đổi nếu điểm nhìn thời gian thay đổi.',
 [['She said that she was testing the app.','Cô ấy nói rằng lúc đó cô ấy đang kiểm thử ứng dụng.','Am testing → was testing khi thuật lại từ điểm nhìn quá khứ.'],['He asked me where I worked.','Anh ấy hỏi tôi làm ở đâu.','Không đảo where did I work trong câu hỏi gián tiếp.']],
 'He told that ... → He said that ... / He told me that ... . He asked where did I live → where I lived.',
 'Đổi điểm nhìn, giữ ý nghĩa','“I am busy,” she said. → She said she was busy. Nếu việc vẫn đúng và người nói muốn giữ tính hiện tại, she said she is busy cũng có thể phù hợp.',
 'He asked me where ___. (standard reported-question order)',['did I work','I worked','do I work','worked I'],1,
 ['Câu hỏi tường thuật không giữ đảo trợ động từ như câu hỏi trực tiếp.','Đúng: where + chủ ngữ + động từ.','Không dùng trật tự câu hỏi trực tiếp ở đây.','Không đảo động từ worked trước chủ ngữ I.']);
lesson('third-conditional','b2','Third Conditional','Điều kiện loại 3','Tưởng tượng một quá khứ khác với thực tế và kết quả quá khứ khác đi cùng với nó.',
 ['If + had + V3, would have + V3','could/might have + V3 cho kết quả có thể','If + had not + V3, would not have + V3'],
 ['Giả định trái với chuyện đã xảy ra trong quá khứ.','Tiếc nuối hoặc phân tích nguyên nhân sau sự kiện.','Would have: kết quả giả định; might/could have: khả năng.'],
 'Cả điều kiện và kết quả đều hướng về quá khứ.',
 [['If we had tested it earlier, we would have found the bug.','Nếu kiểm thử sớm hơn, chúng tôi đã tìm được lỗi.','Thực tế đã không kiểm thử đủ sớm.'],['If I had left earlier, I would not have missed the bus.','Nếu đi sớm hơn, tôi đã không lỡ xe buýt.','Tưởng tượng lại một quá khứ đã kết thúc.']],
 'If I would have left → If I had left trong mẫu chuẩn. Would have + V3 là kết quả, không đặt vào mệnh đề if thông thường.',
 'Nếu đã ... thì đã ...','Loại 2: If I had time, I would help. → hiện tại. Loại 3: If I had had time, I would have helped. → quá khứ.',
 'If we had backed up the data, we ___ it yesterday.',['would not lose','will not lose','would not have lost','do not lose'],2,
 ['Would not lose là kết quả hiện tại/tương lai, không khớp yesterday trong câu này.','Will not lose hướng tương lai.','Đúng: would not have + V3 cho kết quả giả định quá khứ.','Do not lose là hiện tại, không khớp giả định quá khứ.']);
lesson('wish','b2','Wish & if only','Ước muốn khác với thực tế','Sau wish, dạng quá khứ có thể nói điều không đúng ở hiện tại; past perfect nói tiếc nuối về quá khứ.',
 ['wish + past simple: hiện tại khác đi','wish + had + V3: tiếc quá khứ','wish + would + V: muốn tình huống/hành vi thay đổi'],
 ['I wish I knew: hiện tại chưa biết.','I wish I had known: trước đây đã không biết.','Wish + could diễn tả khả năng mong muốn.','Wish + would thường nói tình huống thay đổi hoặc sự khó chịu với hành vi.'],
 'Tách thời gian thật khỏi hình thức động từ sau wish.',
 [['I wish I had more time to study.','Tôi ước hiện tại có nhiều thời gian học hơn.','Had là dạng quá khứ nhưng nói hiện tại.'],['I wish I had saved the file.','Tôi ước lúc đó đã lưu tệp.','Had saved nói tiếc nuối quá khứ.']],
 'I wish I have more time → I wish I had more time. Hope khác wish: I hope the test goes well nói mong một khả năng thực tế.',
 'Wish: thực tế khác mong muốn','I wish I knew. → giờ chưa biết. I wish I had known. → lúc đó đã không biết.',
 'I deleted the file yesterday. I wish I ___ it.',['save','will save','had saved','have saved'],2,
 ['Save không diễn tả tiếc nuối về sự kiện quá khứ.','Will save là tương lai.','Đúng: wish + past perfect cho tiếc nuối quá khứ.','Have saved là present perfect, không phải mẫu tiếc nuối này.']);
lesson('past-modals','b2','Modals about the past','Suy đoán, trách nhiệm và tiếc nuối quá khứ','Modal + have + V3 nhìn về một việc trước thời điểm nói. Ý nghĩa phụ thuộc modal, không phải lúc nào cũng là một sự việc có thật.',
 ['must / might / cannot have + V3','should / should not have + V3','could have + V3'],
 ['Must have: suy luận rất có cơ sở về quá khứ.','Might have: có thể đã xảy ra. Cannot have: gần như không thể đã xảy ra.','Should have: điều đáng lẽ nên làm; thường thực tế không làm.','Could have: khả năng đã có hoặc suy đoán, tùy ngữ cảnh.'],
 'Have ở đây đi sau modal; không chia has.',
 [['The server must have restarted overnight.','Chắc hẳn máy chủ đã khởi động lại trong đêm.','Suy đoán dựa trên dấu vết.'],['I should have checked the logs first.','Đáng lẽ tôi nên kiểm tra log trước.','Tiếc vì đã không làm việc đó.']],
 'He might has left → He might have left. Must have done là suy đoán về quá khứ; nghĩa vụ quá khứ thường dùng had to do.',
 'Modal + have + V3','Must have done: chắc hẳn đã làm. Had to do: đã phải làm. Should have done: đáng lẽ nên làm.',
 'I did not make a backup, and now the data is gone. I ___ a backup.',['must make','should have made','should make yesterday','have to made'],1,
 ['Must make nói nghĩa vụ hiện tại, không nói tiếc nuối trước sự cố.','Đúng: đáng lẽ nên sao lưu nhưng thực tế không làm.','Should make không phối hợp với yesterday theo cách này.','Have to phải đi với V nguyên mẫu; made không đúng cấu trúc.']);
lesson('meaning-changing-verbs','b2','Stop, remember & try','V-ing / to V làm đổi nghĩa','Một số động từ dùng được cả V-ing và to V nhưng ý nghĩa thay đổi. Phải hiểu hành động nào đã xảy ra và mục đích là gì.',
 ['stop doing: ngừng việc đó; stop to do: dừng để làm','remember doing: nhớ đã làm; remember to do: nhớ phải làm','try doing: thử cách; try to do: cố làm'],
 ['Stop working: ngừng làm việc. Stop to drink: dừng việc khác để uống.','Remember locking: nhớ việc đã khóa. Remember to lock: nhớ thực hiện việc khóa.','Try restarting: thử khởi động lại như một giải pháp. Try to restart: cố khởi động lại.'],
 'Đừng chấm theo “stop luôn + V-ing”; nghĩa quyết định cấu trúc.',
 [['I stopped working at six.','Tôi ngừng làm việc lúc sáu giờ.','Hoạt động làm việc kết thúc.'],['I stopped to answer a call.','Tôi dừng lại để nghe một cuộc gọi.','Dừng hoạt động khác nhằm nghe điện thoại.']],
 'Remember to send the file không khẳng định đã gửi; remember sending the file thường nói ký ức về việc đã gửi.',
 'Đổi dạng, đổi nghĩa','Try restarting the app. → thử cách này. Try to restart the app. → cố gắng thực hiện việc này.',
 'He was driving and stopped ___ a phone call. (purpose of stopping)',['answering','to answer','answer','answered'],1,
 ['Stopped answering nghĩa là ngừng nghe/trả lời, không phải dừng lái xe để nghe.','Đúng: stop to do nêu mục đích dừng lại.','Sau stopped không dùng nguyên mẫu trần trong cấu trúc này.','Answered không tạo cấu trúc mục đích sau stopped.']);
lesson('connectors','b2','Although, despite & however','Liên kết và đối lập ý','Chọn từ nối theo quan hệ ý và cấu trúc đi sau. Cùng nghĩa đối lập nhưng although, despite và however không có cùng cú pháp.',
 ['although/even though + S + V','despite/in spite of + danh từ / V-ing','Câu 1. However, câu 2.'],
 ['Although/even though nối một mệnh đề nhượng bộ.','Despite/in spite of đi với danh từ hoặc V-ing; despite the fact that + mệnh đề.','However là trạng từ nối; viết câu riêng hoặc dùng dấu chấm phẩy phù hợp.','Because + mệnh đề; because of + danh từ/V-ing.'],
 'Nhìn thứ đứng ngay sau từ nối: một mệnh đề hay một cụm danh từ?',
 [['Although the task was difficult, we finished it.','Mặc dù nhiệm vụ khó, chúng tôi đã hoàn thành.','Although + the task was difficult, một mệnh đề.'],['Despite being tired, I kept studying.','Dù mệt, tôi vẫn tiếp tục học.','Despite + V-ing.']],
 'Although ... but ... trong cùng mẫu câu chuẩn thường bỏ but. Despite of → despite. However không nối hai câu độc lập chỉ bằng một dấu phẩy.',
 'Although + câu · despite + cụm','Although it rained, we played. / Despite the rain, we played. Hai cấu trúc diễn đạt cùng sự đối lập.',
 '___ being tired, she finished the report.',['Although','Despite','Because','Despite of'],1,
 ['Although thường cần mệnh đề có chủ ngữ và động từ chia thì trong mẫu đang học.','Đúng: despite + V-ing.','Because thường cần mệnh đề và cũng đổi quan hệ đối lập thành nguyên nhân.','Despite không có of; in spite of mới có of.']);
lesson('used-to','b2','Used to & be used to','Thói quen cũ và sự quen thuộc','Used to do nói quá khứ đã khác hiện tại. Be used to doing nói đã quen với một việc; get used to doing nói quá trình trở nên quen.',
 ['used to + V: thói quen/trạng thái cũ','be used to + danh từ / V-ing: đã quen','get used to + danh từ / V-ing: dần quen'],
 ['Used to diễn tả thói quen hoặc trạng thái trước đây không còn đúng.','Would kể thói quen lặp lại trong quá khứ khi đã có bối cảnh; thường không thay used to cho trạng thái.','Be/get used to có thể chia thì theo thời điểm thật.'],
 'To trong be/get used to là giới từ, nên theo sau bằng V-ing.',
 [['I used to work late every night.','Trước đây tôi thường làm muộn mỗi tối.','Thói quen cũ; hiện tại đã khác.'],['I am getting used to waking up early.','Tôi đang dần quen với việc dậy sớm.','Quá trình thích nghi hiện tại.']],
 'I am used to wake up → waking up. Sau did: Did you use to ...? / I did not use to ... là cách viết chuẩn phổ biến.',
 'Ngày trước ≠ đã quen','I used to work here. → trước đây làm ở đây. I am used to working here. → quen với việc làm ở đây.',
 'I am used to ___ early now.',['wake up','waking up','woke up','be waking up'],1,
 ['To là giới từ trong be used to, không đi với V nguyên mẫu.','Đúng: be used to + V-ing.','V2 không đi sau be used to trong cấu trúc này.','Be waking up không phải danh động từ được yêu cầu.']);

lesson('future-perfect-continuous','b2plus','Future Perfect Continuous','Tương lai hoàn thành tiếp diễn','Đứng tại một mốc tương lai và đo thời lượng của hoạt động đã diễn ra đến mốc ấy. Đây là dạng ít dùng hơn, học sau các dạng thông dụng.',F.fpc,
 ['Nhấn thời lượng hoạt động tính đến một mốc tương lai.','Không khẳng định hoạt động phải kết thúc ngay tại mốc.','Thường không dùng với động từ trạng thái như know; dùng future perfect simple.'],
 'By ... + for ... thường giúp biểu thị mốc và thời lượng.',
 [['By ten, I will have been studying for two hours.','Đến mười giờ, tôi sẽ học được hai tiếng.','Thời lượng tính đến mốc mười giờ.'],['By next month, she will have been training for a year.','Đến tháng sau, cô ấy sẽ tập luyện được một năm.','Nhấn quá trình có thể vẫn tiếp tục sau mốc.']],
 'Will have been study → studying. Không dùng dạng này chỉ để nói việc sẽ đang xảy ra lúc nào; đó thường là future continuous.',
 'Đến mốc đó, đã làm được bao lâu','At ten, I will be studying. → đang học. By ten, I will have been studying for two hours. → thời lượng đến mười giờ.',
 'By ten tomorrow, I ___ for two hours. (focus on duration up to that point)',['will be study','will have been studying','have been studied','had study'],1,
 ['Will be phải đi với studying, không phải study để tạo tiếp diễn.','Đúng: will have been + V-ing, nhấn thời lượng đến mốc tương lai.','Have been studied là bị động, không phù hợp chủ ngữ người học và điểm nhìn tương lai.','Had study sai cấu trúc.'],'future-perfect-continuous');
lesson('mixed-conditionals','b2plus','Mixed Conditionals','Điều kiện hỗn hợp','Thời gian của nguyên nhân giả định và kết quả giả định có thể khác nhau. Xác định thời gian thật ở từng mệnh đề trước khi chọn dạng.',
 ['quá khứ → hiện tại: If + had V3, would + V','hiện tại → quá khứ: If + past simple, would have + V3','Giữ thời gian và ý nghĩa nhất quán ở từng mệnh đề'],
 ['Nguyên nhân quá khứ, hậu quả giả định hiện tại.','Một đặc điểm hiện tại có thể giải thích kết quả giả định trong quá khứ.','Không trộn cấu trúc tùy ý; cần ý nghĩa liên kết giữa hai thời điểm.'],
 'Then, yesterday, now giúp làm rõ thời gian ở mỗi mệnh đề.',
 [['If I had slept earlier, I would feel better now.','Nếu tối qua ngủ sớm hơn, giờ tôi đã thấy khỏe hơn.','Nguyên nhân quá khứ, kết quả hiện tại.'],['If I were more careful, I would not have deleted that file.','Nếu là người cẩn thận hơn, tôi đã không xóa tệp đó.','Đặc điểm hiện tại, kết quả giả định trong quá khứ.']],
 'Không coi mọi if + had V3 đều phải đi với would have V3. Nếu kết quả là hiện tại, would + V có thể đúng.',
 'Mỗi mệnh đề có thời gian riêng','Loại 3: would have felt better yesterday. Hỗn hợp: would feel better now.',
 'If I had gone to bed earlier last night, I ___ so tired now.',['would not be','would not have been','will not be','had not been'],0,
 ['Đúng: kết quả giả định ở hiện tại now → would not be.','Would not have been đặt kết quả ở quá khứ, không khớp now.','Will not be nói kết quả tương lai thực tế, không khớp điều kiện trái quá khứ.','Had not been không tạo mệnh đề kết quả giả định trong mẫu này.'],'mixed');
lesson('advanced-passive','b2plus','Reporting passive & causative','Bị động tường thuật và nhờ người làm','Bị động tường thuật trình bày thông tin theo nguồn chung. Cấu trúc have/get something done nói việc được sắp xếp cho người khác thực hiện.',
 ['It is said/believed that + mệnh đề','S + is said/believed + to V / to have V3','have/get + tân ngữ + V3'],
 ['It is believed that ...: người ta tin rằng.','To have + V3 khi sự việc có trước thời điểm tường thuật.','Have/get something done thường nói thuê/nhờ/sắp xếp công việc.','Have something stolen cũng có thể nói trải nghiệm bị mất; không phải luôn là chủ động nhờ người khác.'],
 'Tách người thực hiện khỏi người sắp xếp hoặc chịu tác động.',
 [['The company is believed to have changed its policy.','Người ta tin rằng công ty đã thay đổi chính sách.','To have changed: việc thay đổi có trước nhận định hiện tại.'],['I had my laptop repaired yesterday.','Hôm qua tôi đã đem máy tính đi sửa.','Người khác sửa, tôi sắp xếp việc sửa.']],
 'I had repaired my laptop → tôi đã tự sửa xong trước một mốc quá khứ. I had my laptop repaired → tôi nhờ/đem máy đi sửa. Vị trí tân ngữ làm đổi cấu trúc.',
 'Have something done','I repaired my laptop. → tôi sửa. I had my laptop repaired. → người khác sửa cho tôi.',
 'I paid a technician to fix it. I had my laptop ___ yesterday.',['repair','repairing','repaired','to repair'],2,
 ['Have + object + V3 mới là mẫu nhờ người thực hiện.','Repairing không phải V3 trong cấu trúc này.','Đúng: had my laptop repaired.','To repair không dùng trong mẫu have something done.']);
lesson('reduced-relatives','b2plus','Reduced relative clauses','Rút gọn mệnh đề quan hệ','Rút gọn phần mô tả danh từ khi cấu trúc cho phép. V-ing thường mang nghĩa chủ động; V3 thường mang nghĩa bị động.',
 ['people who are working → people working','files that were sent → files sent','the first person to arrive: to-infinitive trong mẫu phù hợp'],
 ['Dạng -ing mô tả chủ thể thực hiện hành động.','Dạng V3 mô tả đối tượng chịu tác động.','Không thể xóa who/which và mọi trợ động từ trong mọi loại mệnh đề; phải bảo toàn nghĩa.'],
 'Rút gọn làm câu gọn hơn, không tự động khiến câu hay hơn.',
 [['The files sent yesterday contain the results.','Các tệp được gửi hôm qua chứa kết quả.','Sent yesterday rút gọn that were sent yesterday.'],['The engineer working on this feature is on leave.','Kỹ sư đang làm tính năng này đang nghỉ phép.','Working rút gọn who is working.']],
 'The files sending yesterday mang nghĩa tệp tự gửi, khác nghĩa bị động muốn nói. Đừng nhầm cụm rút gọn với vị ngữ chính của câu.',
 'V-ing chủ động · V3 bị động','The person testing the app ... → người kiểm thử. The app tested yesterday ... → ứng dụng được kiểm thử.',
 'The documents ___ yesterday are on your desk. (documents were sent)',['sending','sent','send','are sent'],1,
 ['Sending có nghĩa chủ động, trái documents were sent.','Đúng: sent rút gọn which were sent.','Send nguyên mẫu không tạo cụm quan hệ rút gọn này.','Are sent sẽ tạo hai vị ngữ hữu hạn không được nối: are sent ... are ... .']);
lesson('participle-clauses','b2plus','Participle clauses','Mệnh đề phân từ','Dùng cụm V-ing, V3 hoặc having + V3 để gói thông tin nền như lý do, thời gian hoặc hành động đã xong. Chủ thể phải rõ.',
 ['V-ing ..., S + V: chủ động','V3 ..., S + V: bị động','Having + V3 ..., S + V: hành động trước đó'],
 ['Thường dùng trong văn viết, diễn đạt gọn.','Chủ thể hiểu ngầm của cụm phân từ thường trùng chủ ngữ mệnh đề chính.','Having done nhấn việc hoàn thành trước hành động chính.'],
 'Hỏi: ai đang thực hiện hành động trong cụm đầu câu?',
 [['Having checked the logs, I restarted the server.','Sau khi kiểm tra log, tôi khởi động lại máy chủ.','Tôi làm cả hai; kiểm tra diễn ra trước.'],['Written in plain English, the guide is easy to follow.','Được viết bằng tiếng Anh dễ hiểu, hướng dẫn này dễ làm theo.','Guide là thứ được viết.']],
 'Walking to work, the rain started là dangling participle: câu ngầm biến the rain thành người đi bộ. Sửa: While I was walking to work, it started raining.',
 'Cùng chủ thể, rõ thứ tự','Checking the logs, I noticed an error. → đang kiểm tra thì thấy. Having checked the logs, I restarted. → kiểm tra xong rồi khởi động lại.',
 '___ the logs, I restarted the server. (checking was complete first)',['Having checked','Have checked','Checks','Was checked'],0,
 ['Đúng: having + V3 cho việc hoàn tất trước; I là chủ thể của cả hai hành động.','Have checked có động từ chia thì nhưng thiếu chủ ngữ trong cụm đầu.','Checks không tạo mệnh đề phân từ.','Was checked là bị động, không phù hợp ý tôi kiểm tra log.']);
lesson('indirect-questions','b2plus','Indirect questions','Câu hỏi gián tiếp và lịch sự','Dùng một phần mở đầu lịch sự rồi giữ trật tự chủ ngữ + động từ trong phần câu hỏi được nhúng.',
 ['Could you tell me + wh-word + S + V?','Do you know + if/whether + S + V?','I wonder + wh-word/if + S + V.'],
 ['Wh-questions: where the office is, when it starts.','Yes/no: if/whether the app is ready.','Không đảo trợ động từ trong phần được nhúng.','Nếu who chính là chủ ngữ, trật tự có thể nhìn giống câu hỏi trực tiếp: who called.'],
 'Could you tell me là câu hỏi ngoài; phần bên trong dùng trật tự câu trần thuật.',
 [['Could you tell me when the meeting starts?','Bạn có thể cho tôi biết cuộc họp bắt đầu lúc nào không?','When the meeting starts, không phải when does the meeting start.'],['Do you know whether the update is ready?','Bạn có biết bản cập nhật đã sẵn sàng chưa?','Whether mở câu hỏi yes/no được nhúng.']],
 'Do you know where is he? → Do you know where he is? Không nhầm việc đảo ở mệnh đề hỏi ngoài với trật tự ở phần trong.',
 'Ngoài hỏi, trong kể','Where is the office? → trực tiếp. Could you tell me where the office is? → gián tiếp.',
 'Could you tell me where ___?',['is the office','the office is','does the office','office is the'],1,
 ['Đây là trật tự câu hỏi trực tiếp, không dùng ở phần nhúng.','Đúng: where + S + V.','Does the office thiếu động từ chính và sai trật tự cho câu này.','Sai trật tự danh từ và mạo từ.']);
lesson('quantifiers','b2plus','Quantifiers & agreement','Lượng từ và hòa hợp chủ ngữ','Lượng từ nói số lượng và phạm vi. Cấu trúc danh từ theo sau quyết định nghĩa, còn hạt nhân chủ ngữ quyết định chia động từ.',
 ['each/every + danh từ số ít + V số ít','both + danh từ số nhiều; either/neither of + nhóm hai','a number of + số nhiều; the number of + V số ít'],
 ['Each/every đi với danh từ số ít, chia số ít.','Both nói cả hai; either một trong hai; neither không bên nào.','A number of developers are ...; the number of developers is ... .','Neither of thường dùng V số ít trong văn viết trang trọng; V số nhiều có thể gặp trong văn nói.'],
 'Xác định hạt nhân chủ ngữ trước khi nhìn danh từ gần động từ.',
 [['Each developer has a test device.','Mỗi lập trình viên có một thiết bị kiểm thử.','Each developer là chủ ngữ số ít.'],['The number of users is increasing.','Số lượng người dùng đang tăng.','Chủ ngữ chính là the number, không phải users.']],
 'Every developers have → Every developer has. Danh từ gần động từ không tự động là chủ ngữ chính.',
 'The number is · a number are','A number of users are online. → nhiều người dùng đang online. The number of users is high. → số lượng cao.',
 'The number of active users ___ increasing.',['are','is','have','were'],1,
 ['Hạt nhân chủ ngữ là the number, số ít.','Đúng: the number ... is increasing.','Have không tạo tiếp diễn và không hợp số ít.','Were là số nhiều quá khứ, không khớp mẫu hiện tại này.']);
lesson('inversion','b2plus','Emphatic inversion','Đảo ngữ nhấn mạnh · mở rộng','Một số cụm phủ định/hạn định ở đầu câu kích hoạt đảo trợ động từ trước chủ ngữ. Đây là phần mở rộng nâng cao, thường gặp trong văn trang trọng.',
 ['Never/Rarely + trợ động từ + S + V','Not until ... + trợ động từ + S + V','Only after ... + trợ động từ + S + V'],
 ['Never have I seen ...; Rarely do we encounter ... .','Nếu không sẵn trợ động từ, dùng do/does/did.','Only after/Not until đứng đầu: đảo ở mệnh đề chính, không đảo mệnh đề thời gian.','Đây là phần mở rộng tiếp giáp nội dung C1; không cần lạm dụng để học chắc B2.'],
 'Đảo khi cụm hạn định phù hợp đứng đầu; never ở giữa câu không yêu cầu đảo.',
 [['Never have I seen such a confusing error.','Tôi chưa từng thấy lỗi nào khó hiểu đến thế.','Never đứng đầu → have trước I.'],['Only after checking the logs did I find the cause.','Chỉ sau khi xem log tôi mới tìm ra nguyên nhân.','Did ở mệnh đề chính, find trở về nguyên mẫu.']],
 'Never I have seen → Never have I seen. Only after I checked did I found → did I find. Không dùng đảo ngữ cho every/always ở đầu câu một cách máy móc.',
 'Đầu phủ định → đảo trợ động từ','I have never seen it. → trật tự thường. Never have I seen it. → nhấn mạnh trang trọng.',
 'Never ___ such a strange bug.',['I have seen','have I seen','I seen','have seen I'],1,
 ['Never đứng đầu trong cấu trúc này yêu cầu đảo have trước chủ ngữ.','Đúng: Never + have + I + seen.','Thiếu trợ động từ và sai V2/V3.','Không đặt seen trước chủ ngữ; chỉ đảo trợ động từ.']);
lesson('cleft-sentences','b2plus','Cleft sentences','Câu chẻ để nhấn mạnh · mở rộng','Tách câu thành hai phần để làm nổi bật một thông tin: ai, điều gì hoặc thời điểm nào. Giúp điều chỉnh trọng tâm, không phải để làm câu dài.',
 ['It is/was + phần nhấn + that/who + ...','What + mệnh đề + be + phần nhấn','All I need is ...'],
 ['It was Lan who fixed it: nhấn người sửa.','It was yesterday that ...: nhấn thời điểm.','What I need is ...: nhấn thứ đang cần.','Phần mở rộng nâng cao; trước hết dùng câu thường chính xác.'],
 'Hỏi: muốn người nghe chú ý vào thành phần nào?',
 [['It was Lan who fixed the login bug.','Chính Lan là người đã sửa lỗi đăng nhập.','Nhấn người thực hiện.'],['What I need is more time to practise.','Điều tôi cần là thêm thời gian luyện tập.','Nhấn nhu cầu, không phải người cần.']],
 'It was Lan who fixed it không phải bị động; Lan vẫn là người làm. Tránh dùng câu chẻ ở mọi câu trong bài viết vì sẽ nặng và thiếu tự nhiên.',
 'Đổi trọng tâm, giữ sự kiện','Lan fixed the bug yesterday. → trung tính. It was yesterday that Lan fixed it. → nhấn thời điểm.',
 'It was Lan ___ fixed the bug. (emphasis on the person)',['which','who','what','where'],1,
 ['Which thường chỉ vật, không phù hợp nhấn người Lan.','Đúng: It was Lan who ...; that cũng có thể dùng nhưng không nằm trong lựa chọn.','What không nối theo mẫu It was Lan ... này.','Where chỉ nơi chốn, không chỉ người.']);
lesson('adverb-scope','b2plus','Adverbs & shades of meaning','Vị trí trạng từ và sắc thái','Vị trí của only và cách chọn quite, very, absolutely có thể thay đổi thông tin được nhấn. Đọc câu theo nghĩa, không chỉ theo cấu trúc.',
 ['only + phần được giới hạn (chọn vị trí rõ nghĩa)','very/really + gradable adjective','absolutely/completely + non-gradable adjective phù hợp'],
 ['Only thay đổi phạm vi: only I / I only tested / only the login screen.','Very cold nhưng absolutely freezing là tổ hợp phổ biến.','Quite có thể mang nghĩa khác theo tính từ và biến thể tiếng Anh; không dịch một nghĩa cố định.','Trạng từ tần suất thường trước động từ chính, sau be, và sau trợ động từ đầu tiên.'],
 'Đọc: điều gì đang bị giới hạn hoặc tăng mức độ?',
 [['Only I tested the login screen.','Chỉ mình tôi kiểm thử màn hình đăng nhập.','Giới hạn người thực hiện.'],['I tested only the login screen.','Tôi chỉ kiểm thử màn hình đăng nhập.','Giới hạn đối tượng được kiểm thử.']],
 'I only tested the login screen có thể mơ hồ trong thực tế; đặt only sát phần cần giới hạn để rõ nghĩa. Very exhausted thường kém tự nhiên hơn absolutely exhausted.',
 'Only đứng đâu, nhấn chỗ đó','Only I tested it: chỉ tôi. I only tested it: chỉ kiểm thử, không làm việc khác. I tested only it: chỉ đối tượng đó.',
 '___ tested the app. (I was the only person who tested it.)',['Only I','I only','I tested only','Only tested I'],0,
 ['Đúng: Only I giới hạn người thực hiện, chỉ mình tôi.','I only tested thường giới hạn hành động; không nói rõ chỉ mình tôi.','Sẽ lặp tested và sai cấu trúc khi chèn vào đề.','Sai trật tự chủ ngữ và động từ.']);

const TENSE_IDS=['present-simple','present-continuous','present-perfect','present-perfect-continuous','past-simple','past-continuous','past-perfect','past-perfect-continuous','future-simple','future-continuous','future-perfect','future-perfect-continuous'];
